[ApiController]
[Route("api/v{version:apiVersion}/[controller]")]
public sealed class ProductsController : ControllerBase
{
    // GET api/v1/products/42
    [HttpGet("{id:int}")]
    public ActionResult<ProductDto> GetById(int id) => Ok(new ProductDto(id));

    // GET api/v1/products/search?q=phone — literal segment beats {id}
    [HttpGet("search")]
    public ActionResult<IEnumerable<ProductDto>> Search([FromQuery] string q)
        => Ok([]);

    // GET api/v1/products/featured — same precedence lesson
    [HttpGet("featured")]
    public ActionResult<ProductDto> Featured() => Ok(new ProductDto(0));
}

var api = app.MapGroup("/api/v1/products");

api.MapGet("/{id:int}", (int id) => Results.Ok(new { id }))
   .WithName("GetProduct");

api.MapGet("/search", (string q) => Results.Ok(new { q }))
   .WithName("SearchProducts");

// Catch-all must be last and is rarely needed in REST APIs
api.MapGet("/{**slug}", (string slug) => Results.NotFound($"Unknown: {slug}"));

[HttpPost]
public IActionResult Create([FromBody] CreateProductRequest request)
{
    var id = 42;
    // Generates URL using route name and values
    var url = Url.Link("GetProduct", new { id });
    return Created(url!, new ProductDto(id));
}

// Minimal API equivalent:
products.MapPost("/", (CreateProductRequest req) =>
{
    var id = 42;
    return Results.CreatedAtRoute("GetProduct", new { id }, new { id });
});
